using Meridian.Core.CodeSync;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Meridian.Serialization.CodeSync;

/// <summary>
/// Reads C# sources into a language-neutral <see cref="CodeModel"/> with Roslyn: every file goes into one compilation
/// (referencing only the core library), so member types, base types and usages resolve across files. Types declared
/// elsewhere (NuGet packages, other assemblies) stay unresolved and fall back to their syntax names. Generated files are
/// skipped, files with syntax errors are read as far as Roslyn recovers (with a warning), and the output is
/// deterministic: types sorted by symbol, members in declaration order.
/// </summary>
public sealed class CSharpCodeReader : ICodeReader
{
    /// <summary>Stop collecting types beyond this many (a warning says so).</summary>
    public int MaxTypes { get; init; } = 50_000;

    /// <summary>Files longer than this (characters) are skipped with a warning.</summary>
    public int MaxFileLength { get; init; } = 2_000_000;

    /// <summary>Stop reading files once their total length exceeds this (characters); a warning says so.</summary>
    public long MaxTotalLength { get; init; } = 200_000_000;

    /// <summary>Uses recorded per (type, target) in <see cref="CodeType.DependencyLocations"/>; the rest are only counted.</summary>
    public int MaxDependencyUsesPerTarget { get; init; } = CodeDependencyUses.DefaultMaxPerTarget;

    /// <summary>Read method bodies into <see cref="CodeMember.Body"/> (behaviour diagrams from code).</summary>
    public bool ReadBodies { get; init; } = true;

    /// <summary>Body statements kept per read in total; later bodies are left out with a warning.</summary>
    public int MaxTotalBodyStatements { get; init; } = CodeBodies.DefaultMaxTotalStatements;

    public string Language => "csharp";

    public bool Handles(string path) =>
        path.EndsWith(".cs", StringComparison.OrdinalIgnoreCase) && !IsGeneratedPath(path);

    /// <summary>obj/ and bin/ folders, *.g.cs, *.g.i.cs, *.Designer.cs and *.AssemblyInfo.cs.</summary>
    public static bool IsGeneratedPath(string path)
    {
        var p = "/" + path.Replace('\\', '/').TrimStart('/');
        return p.Contains("/obj/", StringComparison.OrdinalIgnoreCase) || p.Contains("/bin/", StringComparison.OrdinalIgnoreCase)
            || p.EndsWith(".g.cs", StringComparison.OrdinalIgnoreCase) || p.EndsWith(".g.i.cs", StringComparison.OrdinalIgnoreCase)
            || p.EndsWith(".designer.cs", StringComparison.OrdinalIgnoreCase) || p.EndsWith(".AssemblyInfo.cs", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>A file whose header comment says &lt;auto-generated&gt; (checked in the leading trivia only).</summary>
    public static bool IsGeneratedContent(string content)
    {
        var head = content.Length > 4096 ? content[..4096] : content;
        var i = 0;
        // Only look at the leading comment block, not at string literals further down.
        while (i < head.Length)
        {
            while (i < head.Length && char.IsWhiteSpace(head[i])) i++;
            if (i + 1 < head.Length && head[i] == '/' && head[i + 1] == '/')
            {
                var end = head.IndexOf('\n', i);
                var line = end < 0 ? head[i..] : head[i..end];
                if (line.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase)) return true;
                if (end < 0) break;
                i = end + 1;
            }
            else if (i + 1 < head.Length && head[i] == '/' && head[i + 1] == '*')
            {
                var end = head.IndexOf("*/", i + 2, StringComparison.Ordinal);
                var block = end < 0 ? head[i..] : head[i..end];
                if (block.Contains("<auto-generated", StringComparison.OrdinalIgnoreCase)) return true;
                if (end < 0) break;
                i = end + 2;
            }
            else if (i < head.Length && head[i] == '#') // #nullable, #pragma … before the header
            {
                var end = head.IndexOf('\n', i);
                if (end < 0) break;
                i = end + 1;
            }
            else break;
        }
        return false;
    }

    private static readonly HashSet<string> CollectionNames = new(StringComparer.Ordinal)
    {
        "List", "IList", "IEnumerable", "ICollection", "IReadOnlyList", "IReadOnlyCollection", "HashSet", "ISet", "IReadOnlySet",
        "SortedSet", "Collection", "ReadOnlyCollection", "ObservableCollection", "LinkedList", "Queue", "Stack",
        "ImmutableArray", "ImmutableList", "ImmutableHashSet", "IImmutableList", "IImmutableSet", "ConcurrentBag", "ConcurrentQueue",
        "ConcurrentStack", "BlockingCollection", "IAsyncEnumerable", "Span", "ReadOnlySpan", "Memory", "ReadOnlyMemory",
    };

    private static readonly HashSet<string> DictionaryNames = new(StringComparer.Ordinal)
    {
        "Dictionary", "IDictionary", "IReadOnlyDictionary", "SortedDictionary", "SortedList", "ConcurrentDictionary",
        "ImmutableDictionary", "IImmutableDictionary", "FrozenDictionary",
    };

    internal static readonly SymbolDisplayFormat TypeDisplay = SymbolDisplayFormat.MinimallyQualifiedFormat
        .AddMiscellaneousOptions(SymbolDisplayMiscellaneousOptions.IncludeNullableReferenceTypeModifier);

    public CodeModel Read(IReadOnlyList<CodeFile> files, CancellationToken ct = default)
    {
        var warnings = new List<string>();
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest, DocumentationMode.Parse);
        var trees = new List<SyntaxTree>();
        var seenPaths = new HashSet<string>(StringComparer.Ordinal);
        long total = 0;

        foreach (var f in files.OrderBy(f => f.Path, StringComparer.Ordinal))
        {
            ct.ThrowIfCancellationRequested();
            if (!f.Path.EndsWith(".cs", StringComparison.OrdinalIgnoreCase)) continue;
            if (IsGeneratedPath(f.Path)) continue;
            if (!seenPaths.Add(f.Path)) { warnings.Add($"{f.Path}: listed twice, the second copy was ignored."); continue; }
            var content = f.Content ?? "";
            if (content.Length > MaxFileLength) { warnings.Add($"{f.Path}: skipped, larger than {MaxFileLength:N0} characters."); continue; }
            if (IsGeneratedContent(content)) continue;
            total += content.Length;
            if (total > MaxTotalLength)
            {
                warnings.Add($"Stopped reading at {f.Path}: the sources exceed {MaxTotalLength:N0} characters in total.");
                break;
            }
            var tree = CSharpSyntaxTree.ParseText(content, parseOptions, path: f.Path, cancellationToken: ct);
            var errors = tree.GetDiagnostics(ct).Where(d => d.Severity == DiagnosticSeverity.Error).ToList();
            if (errors.Count > 0)
            {
                var first = errors[0];
                var line = first.Location.GetLineSpan().StartLinePosition.Line + 1;
                warnings.Add($"{f.Path}: {errors.Count} syntax error{(errors.Count == 1 ? "" : "s")} (first at line {line}: {first.GetMessage(System.Globalization.CultureInfo.InvariantCulture)}); read what could be recovered.");
            }
            trees.Add(tree);
        }

        var compilation = CSharpCompilation.Create("CodeSync", trees, CoreReferences(),
            new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary, nullableContextOptions: NullableContextOptions.Enable,
                concurrentBuild: false, deterministic: true));

        // Pass 1: declared types, merged across partial declarations.
        var decls = new Dictionary<string, TypeInfo>(StringComparer.Ordinal);
        var capped = false;
        foreach (var tree in trees)
        {
            ct.ThrowIfCancellationRequested();
            var model = compilation.GetSemanticModel(tree);
            foreach (var node in tree.GetRoot(ct).DescendantNodes(n => n is CompilationUnitSyntax or BaseNamespaceDeclarationSyntax or BaseTypeDeclarationSyntax))
            {
                if (node is not BaseTypeDeclarationSyntax decl) continue;
                if (model.GetDeclaredSymbol(decl, ct) is not INamedTypeSymbol sym) continue;
                var key = SymbolOf(sym);
                if (!decls.TryGetValue(key, out var info))
                {
                    if (decls.Count >= MaxTypes)
                    {
                        if (!capped) warnings.Add($"Only the first {MaxTypes:N0} types were read; the rest were skipped.");
                        capped = true;
                        continue;
                    }
                    decls[key] = info = new TypeInfo(key, sym);
                }
                info.Declarations.Add((decl, model));
            }
        }

        // Pass 2: members, inheritance, usage.
        var types = new List<CodeType>(decls.Count);
        var budget = new BodyBudget(ReadBodies ? MaxTotalBodyStatements : 0);
        foreach (var info in decls.Values.OrderBy(i => i.Key, StringComparer.Ordinal))
        {
            ct.ThrowIfCancellationRequested();
            types.Add(BuildType(info, decls, MaxDependencyUsesPerTarget, budget, compilation.GetSemanticModel, ct));
        }
        if (budget.Exhausted) warnings.Add($"Method bodies were read up to {MaxTotalBodyStatements:N0} statements; the bodies of later methods were left out.");
        return new CodeModel(Language, types, warnings);
    }

    private sealed class TypeInfo(string key, INamedTypeSymbol symbol)
    {
        public string Key { get; } = key;
        public INamedTypeSymbol Symbol { get; } = symbol;
        public List<(BaseTypeDeclarationSyntax Syntax, SemanticModel Model)> Declarations { get; } = new();
    }

    private static IEnumerable<MetadataReference> CoreReferences()
    {
        // The core library, plus LINQ and the collections, so lambdas in LINQ calls bind (their calls resolve in bodies).
        foreach (var assembly in new[] { typeof(object).Assembly, typeof(Enumerable).Assembly, typeof(Queue<>).Assembly })
        {
            var location = assembly.Location;
            if (!string.IsNullOrEmpty(location) && File.Exists(location)) yield return MetadataReference.CreateFromFile(location);
        }
        var runtime = Path.Combine(Path.GetDirectoryName(typeof(object).Assembly.Location) ?? "", "System.Runtime.dll");
        if (File.Exists(runtime)) yield return MetadataReference.CreateFromFile(runtime);
    }

    /// <summary>"Ns.Outer`1.Inner": namespace, containing types and the type, with generic arity.</summary>
    private static string SymbolOf(INamedTypeSymbol t)
    {
        var parts = new List<string>();
        for (var x = t; x != null; x = x.ContainingType)
            parts.Add(x.Arity > 0 ? $"{x.Name}`{x.Arity}" : x.Name);
        parts.Reverse();
        var ns = NamespaceOf(t);
        return ns.Length == 0 ? string.Join(".", parts) : ns + "." + string.Join(".", parts);
    }

    private static string NamespaceOf(INamedTypeSymbol t) =>
        t.ContainingNamespace is { IsGlobalNamespace: false } n ? n.ToDisplayString() : "";

    private static string DisplayName(INamedTypeSymbol t) =>
        t.Arity > 0 ? $"{t.Name}<{string.Join(", ", t.TypeParameters.Select(p => p.Name))}>" : t.Name;

    private static CodeType BuildType(TypeInfo info, Dictionary<string, TypeInfo> scanned, int maxUses, BodyBudget budget, Func<SyntaxTree, bool, SemanticModel> modelOf, CancellationToken ct)
    {
        var sym = info.Symbol;
        var ordered = info.Declarations
            .OrderBy(d => d.Syntax.SyntaxTree.FilePath, StringComparer.Ordinal).ThenBy(d => d.Syntax.SpanStart).ToList();
        var first = ordered[0].Syntax;
        var kind = first switch
        {
            InterfaceDeclarationSyntax => CodeTypeKind.Interface,
            EnumDeclarationSyntax => CodeTypeKind.Enum,
            RecordDeclarationSyntax => CodeTypeKind.Record,
            StructDeclarationSyntax => CodeTypeKind.Struct,
            _ => CodeTypeKind.Class,
        };
        var line = first.Identifier.GetLocation().GetLineSpan().StartLinePosition.Line + 1;
        var doc = ordered.Select(d => Doc(d.Syntax)).FirstOrDefault(d => !string.IsNullOrEmpty(d));

        string? Scanned(ITypeSymbol? t) =>
            t is INamedTypeSymbol n && n.TypeKind != TypeKind.Error && n.OriginalDefinition is INamedTypeSymbol od
                && od.Locations.Any(l => l.IsInSource) && scanned.ContainsKey(SymbolOf(od))
                ? SymbolOf(od) : null;

        var bases = new List<string>();
        if (sym.BaseType is { } bt && Scanned(bt) is { } bs) bases.Add(bs);
        var interfaces = sym.Interfaces.Select(i => Scanned(i)).OfType<string>().Distinct().ToList();
        if (kind == CodeTypeKind.Interface)
        {
            // An interface's base interfaces are its generalizations.
            bases.AddRange(interfaces);
            interfaces = [];
        }

        // Members, in declaration order (partial parts in file order).
        var members = new List<CodeMember>();
        var memberTypes = new HashSet<string>(StringComparer.Ordinal);
        var positional = ordered.Select(d => d.Syntax).OfType<RecordDeclarationSyntax>()
            .SelectMany(r => r.ParameterList?.Parameters ?? default).Select(p => p.Identifier.Text).ToHashSet(StringComparer.Ordinal);
        foreach (var m in sym.GetMembers())
        {
            ct.ThrowIfCancellationRequested();
            if (m.IsImplicitlyDeclared && !(m is IPropertySymbol && positional.Contains(m.Name))) continue;
            if (m.DeclaringSyntaxReferences.Length == 0 && !positional.Contains(m.Name)) continue;
            switch (m)
            {
                case IFieldSymbol f when sym.TypeKind == TypeKind.Enum:
                    if (f.HasConstantValue || f.IsConst)
                        members.Add(new CodeMember(f.Name, CodeMemberKind.EnumValue, sym.Name, null, false, "public") { Doc = MemberDoc(f), Line = MemberLine(f) });
                    break;
                case IFieldSymbol f when f.AssociatedSymbol == null:
                {
                    var (ts, many) = ElementType(f.Type, Scanned);
                    if (ts != null) memberTypes.Add(ts);
                    members.Add(new CodeMember(f.Name, CodeMemberKind.Field, f.Type.ToDisplayString(TypeDisplay), ts, many, Visibility(f.DeclaredAccessibility))
                    { IsStatic = f.IsStatic || f.IsConst, Doc = MemberDoc(f), Line = MemberLine(f) });
                    break;
                }
                case IPropertySymbol p when !p.IsIndexer:
                {
                    if (p.Name == "EqualityContract" && p.IsImplicitlyDeclared) break;
                    var (ts, many) = ElementType(p.Type, Scanned);
                    if (ts != null) memberTypes.Add(ts);
                    members.Add(new CodeMember(p.Name, CodeMemberKind.Property, p.Type.ToDisplayString(TypeDisplay), ts, many, Visibility(p.DeclaredAccessibility))
                    { IsStatic = p.IsStatic, IsAbstract = p.IsAbstract && sym.TypeKind != TypeKind.Interface, Doc = MemberDoc(p), Line = MemberLine(p) });
                    break;
                }
                case IMethodSymbol md when md.MethodKind == MethodKind.Ordinary:
                {
                    var (ts, many) = ElementType(md.ReturnType, Scanned);
                    var parameters = md.Parameters.Select(p =>
                    {
                        var (pts, pmany) = ElementType(p.Type, Scanned);
                        var dir = p.RefKind switch
                        {
                            RefKind.Out => CodeParameterDirection.Out,
                            RefKind.Ref => CodeParameterDirection.InOut,
                            _ => CodeParameterDirection.In,
                        };
                        return new CodeParameter(p.Name, p.Type.ToDisplayString(TypeDisplay), pts, pmany, dir);
                    }).ToList();
                    members.Add(new CodeMember(md.Name, CodeMemberKind.Method, md.ReturnType.ToDisplayString(TypeDisplay), ts, many, Visibility(md.DeclaredAccessibility))
                    {
                        Parameters = parameters, IsStatic = md.IsStatic, IsAbstract = md.IsAbstract && sym.TypeKind != TypeKind.Interface,
                        Doc = MemberDoc(md), Line = MemberLine(md), Attributes = AttributeNames(md),
                        Body = budget.Remaining > 0 ? MethodBody(md, Scanned, budget, modelOf, ct) : null,
                    });
                    break;
                }
            }
        }

        // Usage dependencies: every scanned type named in the declaration (bodies, parameters, locals, creations, static
        // calls, return types), minus the type itself, its nested types' own code, member types and base types.
        var excluded = new HashSet<string>(memberTypes, StringComparer.Ordinal) { info.Key };
        foreach (var b in bases) excluded.Add(b);
        foreach (var i in interfaces) excluded.Add(i);
        var deps = new SortedSet<string>(StringComparer.Ordinal);
        // Where each scanned type is used (base lists, member types, bodies): file, line and kind of the use.
        var uses = new List<CodeDependencyUse>();
        void Use(string target, SyntaxNode at, CodeDependencyKind how)
        {
            if (target == info.Key) return;
            var path = at.SyntaxTree.FilePath;
            uses.Add(new CodeDependencyUse(target, path, at.SyntaxTree.GetLineSpan(at.Span, ct).StartLinePosition.Line + 1, how));
        }
        foreach (var (decl, model) in ordered)
        {
            if (decl.BaseList is not { } baseList) continue;
            foreach (var entry in baseList.Types)
                if (model.GetTypeInfo(entry.Type, ct).Type is { } b && Scanned(b) is { } s) Use(s, entry, CodeDependencyKind.Inherit);
        }
        if (kind != CodeTypeKind.Enum)
            foreach (var (decl, model) in ordered)
            {
                foreach (var node in decl.DescendantNodes(n => n == decl || n is not BaseTypeDeclarationSyntax and not BaseListSyntax))
                {
                    ct.ThrowIfCancellationRequested();
                    ITypeSymbol? used = node switch
                    {
                        ImplicitObjectCreationExpressionSyntax ioc => model.GetTypeInfo(ioc, ct).Type,
                        SimpleNameSyntax sn => model.GetSymbolInfo(sn, ct).Symbol as ITypeSymbol,
                        _ => null,
                    };
                    if (used == null) continue;
                    var how = UseKind(node);
                    foreach (var t in Flatten(used))
                        if (Scanned(t) is { } s)
                        {
                            if (!excluded.Contains(s)) deps.Add(s);
                            Use(s, node, how);
                        }
                }
            }
        var (locations, omitted) = CodeDependencyUses.Cap(uses, maxUses);

        return new CodeType(info.Key, DisplayName(sym), NamespaceOf(sym), kind, first.SyntaxTree.FilePath, line, doc,
            bases.Distinct().ToList(), interfaces, members, deps.ToList())
        {
            IsAbstract = sym.IsAbstract && kind is CodeTypeKind.Class or CodeTypeKind.Record && !sym.IsStatic,
            IsStatic = sym.IsStatic,
            DependencyLocations = locations,
            OmittedDependencyLocations = omitted,
            Attributes = AttributeNames(sym),
            ExternalBases = (sym.BaseType is { SpecialType: SpecialType.None } eb && Scanned(eb) is null ? [eb] : Array.Empty<INamedTypeSymbol>())
                .Concat(sym.Interfaces.Where(i => Scanned(i) is null)).Select(x => x.Name).Where(n => n.Length > 0).Distinct().ToList(),
        };
    }

    /// <summary>Statements still to be read in one <see cref="Read"/> (bounded memory on very large code).</summary>
    private sealed class BodyBudget(int total)
    {
        public int Remaining { get; private set; } = total;
        public bool Exhausted { get; private set; }

        public CodeBody? Take(CodeBody? body)
        {
            if (body is null) return null;
            var n = CodeBodies.Count(body.Statements);
            if (n > Remaining) { Exhausted = true; Remaining = 0; return null; }
            Remaining -= n;
            return body;
        }
    }

    private static CodeBody? MethodBody(IMethodSymbol md, Func<ITypeSymbol?, string?> scanned, BodyBudget budget, Func<SyntaxTree, bool, SemanticModel> modelOf, CancellationToken ct)
    {
        foreach (var r in md.DeclaringSyntaxReferences.OrderBy(r => r.SyntaxTree.FilePath, StringComparer.Ordinal).ThenBy(r => r.Span.Start))
        {
            if (r.GetSyntax(ct) is not BaseMethodDeclarationSyntax decl || decl.Body is null && decl.ExpressionBody is null) continue;
            return budget.Take(new CSharpBodyReader(modelOf(r.SyntaxTree, false), scanned, ct).Read(decl));
        }
        return null;
    }

    /// <summary>Attribute names without the "Attribute" suffix, in declaration order.</summary>
    private static IReadOnlyList<string> AttributeNames(ISymbol s)
    {
        var attrs = s.GetAttributes();
        if (attrs.Length == 0) return [];
        return attrs.Select(a => a.AttributeClass?.Name ?? "").Where(n => n.Length > 0)
            .Select(n => n.EndsWith("Attribute", StringComparison.Ordinal) && n.Length > 9 ? n[..^9] : n).Distinct().ToList();
    }

    /// <summary>How the type named at <paramref name="node"/> is used: created, called, a member / parameter / return type,
    /// or anything else (locals, casts, typeof, generic arguments, static member reads).</summary>
    internal static CodeDependencyKind UseKind(SyntaxNode node)
    {
        if (node is ImplicitObjectCreationExpressionSyntax) return CodeDependencyKind.New;
        // Climb from the name to the whole type it is part of (Sat.Battery, Battery?, Battery[], List<Battery>).
        var n = node;
        while (n.Parent is QualifiedNameSyntax or AliasQualifiedNameSyntax or NullableTypeSyntax or ArrayTypeSyntax or TypeArgumentListSyntax
               or GenericNameSyntax or TupleElementSyntax or TupleTypeSyntax or RefTypeSyntax or PointerTypeSyntax or ScopedTypeSyntax)
            n = n.Parent;
        return n.Parent switch
        {
            ObjectCreationExpressionSyntax oc when oc.Type == n => CodeDependencyKind.New,
            ArrayCreationExpressionSyntax => CodeDependencyKind.New,
            ParameterSyntax { Parent.Parent: RecordDeclarationSyntax } p when p.Type == n => CodeDependencyKind.Field,
            ParameterSyntax p when p.Type == n => CodeDependencyKind.Param,
            MethodDeclarationSyntax m when m.ReturnType == n => CodeDependencyKind.Return,
            LocalFunctionStatementSyntax lf when lf.ReturnType == n => CodeDependencyKind.Return,
            OperatorDeclarationSyntax op when op.ReturnType == n => CodeDependencyKind.Return,
            DelegateDeclarationSyntax dd when dd.ReturnType == n => CodeDependencyKind.Return,
            VariableDeclarationSyntax { Parent: BaseFieldDeclarationSyntax } => CodeDependencyKind.Field,
            BasePropertyDeclarationSyntax bp when bp.Type == n => CodeDependencyKind.Field,
            MemberAccessExpressionSyntax { Parent: InvocationExpressionSyntax inv } ma when ma.Expression == n && inv.Expression == ma => CodeDependencyKind.Call,
            _ => CodeDependencyKind.Use,
        };
    }

    /// <summary>The XML summary on the member's declaration (a field's doc sits on its field declaration).</summary>
    private static string? MemberDoc(ISymbol member)
    {
        foreach (var r in member.DeclaringSyntaxReferences.OrderBy(r => r.SyntaxTree.FilePath, StringComparer.Ordinal).ThenBy(r => r.Span.Start))
        {
            var node = r.GetSyntax();
            if (node is VariableDeclaratorSyntax { Parent.Parent: { } decl }) node = decl;
            if (Doc(node) is { } d) return d;
        }
        return null;
    }

    private static int MemberLine(ISymbol member) =>
        member.Locations.Where(l => l.IsInSource).OrderBy(l => l.SourceTree?.FilePath, StringComparer.Ordinal).ThenBy(l => l.SourceSpan.Start)
            .Select(l => l.GetLineSpan().StartLinePosition.Line + 1).FirstOrDefault();

    /// <summary>The type and its type arguments / array element types, recursively.</summary>
    private static IEnumerable<ITypeSymbol> Flatten(ITypeSymbol t, int depth = 0)
    {
        if (depth > 16) yield break;
        switch (t)
        {
            case IArrayTypeSymbol a:
                foreach (var x in Flatten(a.ElementType, depth + 1)) yield return x;
                break;
            case INamedTypeSymbol n:
                yield return n;
                foreach (var arg in n.TypeArguments)
                    foreach (var x in Flatten(arg, depth + 1)) yield return x;
                break;
        }
    }

    /// <summary>The scanned type a member holds (directly, nullable, array, collection or dictionary value), and whether it holds many.</summary>
    private static (string? Symbol, bool Many) ElementType(ITypeSymbol t, Func<ITypeSymbol?, string?> scanned)
    {
        var many = false;
        for (var guard = 0; guard < 8; guard++)
        {
            switch (t)
            {
                case IArrayTypeSymbol a:
                    t = a.ElementType; many = true; continue;
                case INamedTypeSymbol { IsGenericType: true } n when n.OriginalDefinition.SpecialType == SpecialType.System_Nullable_T:
                    t = n.TypeArguments[0]; continue;
                case INamedTypeSymbol { Arity: 1 } n when CollectionNames.Contains(n.Name) && scanned(n) == null:
                    t = n.TypeArguments[0]; many = true; continue;
                case INamedTypeSymbol { Arity: 2 } n when DictionaryNames.Contains(n.Name) && scanned(n) == null:
                    t = n.TypeArguments[1]; many = true; continue;
            }
            break;
        }
        var s = scanned(t);
        return (s, s != null && many);
    }

    private static string Visibility(Accessibility a) => a switch
    {
        Accessibility.Public => "public",
        Accessibility.Protected => "protected",
        Accessibility.Internal => "internal",
        Accessibility.ProtectedOrInternal => "protected internal",
        Accessibility.ProtectedAndInternal => "private protected",
        _ => "private",
    };

    /// <summary>The text of the XML &lt;summary&gt; doc comment, whitespace collapsed; null when there is none.</summary>
    internal static string? Doc(SyntaxNode node)
    {
        foreach (var trivia in node.GetLeadingTrivia())
        {
            if (trivia.GetStructure() is not DocumentationCommentTriviaSyntax doc) continue;
            var summary = doc.Content.OfType<XmlElementSyntax>().FirstOrDefault(x => x.StartTag.Name.ToString() == "summary");
            if (summary == null) continue;
            var sb = new System.Text.StringBuilder();
            foreach (var nt in summary.Content.SelectMany(c => c.DescendantNodesAndTokensAndSelf()))
            {
                if (nt.IsToken)
                {
                    var tok = nt.AsToken();
                    if (tok.IsKind(SyntaxKind.XmlTextLiteralToken)) sb.Append(tok.ValueText);
                    else if (tok.IsKind(SyntaxKind.XmlTextLiteralNewLineToken)) sb.Append(' ');
                }
                else if (nt.AsNode() is XmlCrefAttributeSyntax cref) sb.Append(cref.Cref.ToString());
                else if (nt.AsNode() is XmlNameAttributeSyntax name) sb.Append(name.Identifier.ToString());
            }
            var text = string.Join(" ", sb.ToString().Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries));
            return text.Length == 0 ? null : text;
        }
        return null;
    }
}
